import React, { useState, useEffect } from 'react';
import axios from 'axios';

const Dashboard = () => {
  const [threatData, setThreatData] = useState(null);
  const [alerts, setAlerts] = useState([]);

  // --- CYBER-AI INTEGRATION LOGIC ---
  const checkThreats = async () => {
    try {
      // Hum Python ML Service (Port 8000) ko fake traffic data bhej rahe hain test karne ke liye
      const response = await axios.post('http://localhost:8000/analyze-traffic', {
        ip_source: "192.168.1.101",
        packet_size: Math.floor(Math.random() * 7000), // Random packet size
        request_count: Math.floor(Math.random() * 1500) // Random request count
      });

      setThreatData(response.data);

      // Agar AI kehta hai anomaly hai, toh alert list mein daal do
      if (response.data.is_anomaly) {
        setAlerts(prev => [{
          id: Date.now(),
          msg: response.data.analysis_report,
          level: response.data.threat_level,
          loc: response.data.location
        }, ...prev].slice(0, 5)); // Sirf top 5 alerts dikhao
      }
    } catch (error) {
      console.error("ML Service unreachable", error);
    }
  };

  useEffect(() => {
    const interval = setInterval(checkThreats, 5000); // Har 5 sec mein check karo
    return () => clearInterval(interval);
  }, []);

  return (
    <div style={{ padding: '20px', backgroundColor: '#0d1117', color: 'white', minHeight: '100vh' }}>
      <h1>🛡️ CyberGuard AI: Smart City Monitor</h1>

      {/* Live AI Status Bar */}
      <div style={{ border: '1px solid #30363d', padding: '15px', borderRadius: '8px', marginBottom: '20px', background: '#161b22' }}>
        <h3>Current Node: <span style={{color: '#58a6ff'}}>{threatData?.location || 'Scanning...'}</span></h3>
        <p>System Status: 
          <span style={{ color: threatData?.is_anomaly ? '#ff7b72' : '#3fb950', fontWeight: 'bold', marginLeft: '10px' }}>
            {threatData?.is_anomaly ? '⚠️ THREAT DETECTED' : '✅ SECURE'}
          </span>
        </p>
      </div>

      {/* Real-time Alert Logs */}
      <div style={{ background: '#0d1117', border: '1px solid #30363d', borderRadius: '8px', padding: '15px' }}>
        <h4>Live Threat Logs (Vision 2030 Nodes)</h4>
        {alerts.map(alert => (
          <div key={alert.id} style={{ color: alert.level === 'Critical' ? '#ff7b72' : '#ffa657', marginBottom: '10px', fontSize: '14px' }}>
            [{new Date().toLocaleTimeString()}] ALERT: {alert.msg} at {alert.loc}
          </div>
        ))}
        {alerts.length === 0 && <p style={{color: '#8b949e'}}>Waiting for network traffic analysis...</p>}
      </div>
    </div>
  );
};

export default Dashboard;
